struct Player { hp: i32, name: String }
let mut p = Player { hp: 100, name: "A".into() };
let name_ref = &p.name;
p.hp -= 10;
println!("{name_ref} has {}", p.hp);

impl Player {
    fn heal(&mut self) { self.hp += 10; }
}
let name_ref = &p.name;
p.heal(); // error E0502: borrows all of `p`
println!("{name_ref}");
